function UIMainInteractionOrderRoleNode:Refresh(catId, ind, cb)
    if not catId then
        return
    end
    local data = phoneComp:GetCatDataById(catId)
    if not data then
        return
    end
    self._cb = cb
    self._data = data
    self:FillSelf()

    CfUtils.PlayDelayShowAnimate(self.AnimRoot, ind)
end

function UIMainInteractionOrderRoleNode:FillSelf()
    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._data.catId)
    CfUtils.FillImage(self.ImgIcon, CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId))
    CfUtils.FillText(self.TxtName, PhoneUtils.GetRoleCurName(self._data.catId))

    local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(self._data.catId)
    CfUtils.FillText(self.TxtNumber, level)
    CfUtils.FillText(self.TxtNum, "<size=29><color=#868686>"..exp.."/</size></color>"..PhoneUtils.GetLikabilityLevelUpAllExp(level))
    self.Slider.value = checkNumber(exp) / PhoneUtils.GetLikabilityLevelUpAllExp(level)

    local isCan = PhoneUtils.GetRoleOrderNum(self._data.catId) > 0
    local status = isCan and 1 or 2
    CfUtils.SetUISwitchImage(self.ImgBg1, status)
    KTool.SetActive(self.Lock, not isCan)

    KTool.SetActive(self.Enable, isCan)
    KTool.SetActive(self.Disable, not isCan)

